import os
import shutil
import time

def delete_files(directory):
    for filename in os.listdir(directory):
        if os.path.isfile(os.path.join(directory, filename)):
            os.remove(os.path.join(directory, filename))
        else:
            shutil.rmtree(os.path.join(directory, filename))
    time.sleep(1)
    if os.path.exists(directory):
        os.rmdir(directory)

def main():
    directory = input("Enter the directory you want to delete: ")
    delete_files(directory)

if __name__ == "__main__":
    main()
else:
    main()

import sys
import os
import webapp2
from google.appengine.ext import ndb
from models import User
class MainHandler(webapp2.WSGIApplication, object):
    def get(self):
        user = User.query(User.email == self.request.cookies.get('email')).get()
        if user:
            path = self.request.path
            if path.startswith('/admin') or path == '/':
                self.redirect('/welcome')
            else:
                self.response.headers.add('Content-Type', 'text/html')
                self.response.out.write('<html><body>Access denied</body></html>')
        else:
            self.response.headers.add('Content-Type', 'text/html')
            self.response.out.write('<html><body>You aren\'t logged in!</body></html>')
app = MainHandler([
    webapp2.Route('<path:path>', handler=MainHandler, name='main')
])
def main():
    if os.environ.get('SERVER_SOFTWARE').startswith('Development'):
        template_dir = 'templates_dev'
    else:
        template_dir = 'templates'
    config = None
    if os.path.exists('config.dev'):
        config = dict(webapp2.config.DevConfig())
        config.dev = True
    else:
        config = dict(webapp2.config ProdConfig())
    template_dir = config.template_path[0]
    app.run_dev_server(debug=True, port=8080)
if __name__ == '__main__':
    main()
